const lang=q=>{const cjk=/[㐀-鿿]/.test(q),latin=/[A-Za-z]{2,}/.test(q);return cjk&&latin?'mixed':cjk?'zh':'en';};
const expand=(rows,split)=>rows.map(([id,category,style,query,judgments,options={}])=>({id,split,category,style,language:lang(query),query,scope:options.scope??'S0',judgments,negatives:options.neg??[]}));
export const queries=[...expand(dev,'dev'),...expand(heldout,'heldout')];
